entries[89] = { ["name"] = "Verkrüppeln", ["text"] = "210 Mana 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nVerkrüppelt das Ziel und verringert dessen Bewegungstempo um 40 und erhöht die Zeit zwischen Nahkampfangriffen um 45% und zwischen Distanzangriffen um 45%. Hält 20 Sek. lang an." }
