entries[101] = { ["name"] = "Straucheln", ["text"] = "15 Energie Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBringt den humanoiden Feind zu Fall, wobei 10 Schadenpunkt(e) verursacht werden und der Gegner 3 Sek. lang am Boden liegt. Gewährt 1 Combopunkt(e)." }
