entries[116] = { ["name"] = "Frostblitz", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nSchleudert einen Frostblitz auf den Gegner, der [Quellwert] bis [Quellwert] Frostschaden verursacht und 5 Sek. lang das Bewegungstempo um 40% verringert.", ["unresolvedValues"] = true }
entries[118] = { ["name"] = "Verwandlung", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerwandelt den Feind in ein Schaf und zwingt ihn, 20 Sek. lang so herumzuwandern. Während das Schaf herumwandert, kann es weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[120] = { ["name"] = "Kältekegel", ["text"] = "210 Mana\nSofort 10 sek. Abklingzeit\nZiele in einem kegelförmigen Bereich vor dem Zaubernden erleiden [Quellwert] bis [Quellwert] Frostschaden, und ihr Bewegungstempo wird 8 Sek. lang um 50% verringert.", ["unresolvedValues"] = true }
