entries[587] = { ["name"] = "Essen herbeizaubern", ["text"] = "60 Mana\nWirken in 3 sek.\nZaubert 20 Muffins herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[588] = { ["name"] = "Inneres Feuer", ["text"] = "30 Mana\nSofort\nDer Zaubernde wird von einer Explosion der heiligen Energie erfüllt, die seine Rüstung um 315 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind." }
