entries[693] = { ["name"] = "Seelenstein herstellen (schwach)", ["text"] = "85% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen schwachen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[694] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 22 Punkt(e) Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 Sek. lang dazu, Angriffe auf Euch zu fokussieren." }
entries[695] = { ["name"] = "Schattenblitz", ["text"] = "40 Mana 30 Meter Reichweite\nWirken in 2.2 sek.\nSchleudert einen Schattenblitz auf den Feind und verursacht 26 bis 32 Punkt(e) Schattenschaden." }
entries[696] = { ["name"] = "Dämonenhaut", ["text"] = "120 Mana\nSofort\nSchützt den Zaubernden, indem es 30 Min. lang die Rüstung um 120 erhöht und alle 5 Sek. 5 Punkt(e) Gesundheit wiederherstellt." }
entries[697] = { ["name"] = "Leerwandler beschwören", ["text"] = "100% von Grundmana\nWirken in 10 sek.\nReagenzien:\nSeelensplitter\nBeschwört einen Leerwandler, der unter dem Befehl des Hexenmeisters steht." }
entries[698] = { ["name"] = "Ritual der Beschwörung", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 5 sek.\nReagenzien:\nSeelensplitter\nBeginnt ein Ritual, das das anvisierte Gruppenmitglied beschwört. Um das Ritual zu vervollständigen, werden der Zaubernde und zwei zusätzliche Gruppenmitglieder benötigt. Um teilzunehmen, müssen sich alle Spieler außerhalb eines Kampfes befinden, auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist." }
entries[699] = { ["name"] = "Blutsauger", ["text"] = "85 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt pro Sekunde 17 Punkt(e) Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[700] = { ["name"] = "Schlaf", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersetzt das feindliche Ziel bis zu 20 Sek. lang in Schlaf. Jeglicher zugefügte Schaden wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel schlafen." }
entries[701] = { ["name"] = "Feuerblitz", ["text"] = "10 Mana 30 Meter Reichweite\nWirken in 3 sek.\nÜberzieht ein Ziel mit 19 Feuerschaden." }
entries[702] = { ["name"] = "Fluch der Schwäche", ["text"] = "20 Mana 30 Meter Reichweite\nSofort\nDer vom Ziel verursachte Schaden wird 2 Min. lang um 3 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[703] = { ["name"] = "Erdrosseln", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nErdrosselt den Feind und verursacht 18 Sek. lang 144 Schaden, erhöht durch Eure Angriffskraft. Muss verstohlen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[704] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "35 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 20 erhöht, jedoch die Rüstung um 140 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[705] = { ["name"] = "Schattenblitz", ["text"] = "70 Mana 30 Meter Reichweite\nWirken in 2.8 sek.\nSchleudert einen Schattenblitz auf den Feind und verursacht 52 bis 61 Punkt(e) Schattenschaden." }
entries[706] = { ["name"] = "Dämonenrüstung", ["text"] = "275 Mana\nSofort\nSchützt den Zaubernden und verbessert die Rüstung um 210, den Schattenwiderstand um 3 und stellt alle 5 Sek. 7 Gesundheit wieder her. Hält 30 Min. an." }
entries[707] = { ["name"] = "Feuerbrand", ["text"] = "45 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Gegner und fügt ihm [Quellwert] Feuerschaden sowie im Verlauf von 15 Sek. insgesamt 40 zusätzlichen Feuerschaden zu.", ["unresolvedValues"] = true }
entries[709] = { ["name"] = "Blutsauger", ["text"] = "135 Mana 20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt pro Sekunde 29 Punkt(e) Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[710] = { ["name"] = "Verbannen", ["text"] = "100 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerbannt das feindliche Ziel und verhindert damit jegliche Aktion, macht es aber bis zu 20 Sek. lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden. Funktioniert nur bei Dämonen und Elementaren." }
entries[711] = { ["name"] = "Höllenfeuer", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nÜberzieht alle Feinde in einem Umkreis von 10 Metern mit 69 bis 78 Punkt(en) Flammenschaden." }
