entries[759] = { ["name"] = "Manaachat herbeizaubern", ["text"] = "530 Mana\nWirken in 3 sek.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 375 bis 425 Mana verwendet werden kann.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
