entries[768] = { ["name"] = "Katzengestalt", ["text"] = "55% von Grundmana\nSofort\nGestaltwandlung in Katzengestalt, erhöht Nahkampfangriffskraft um 40 plus Beweglichkeit. Beschützt den Zaubernden auch vor Verwandlungseffekten und erlaubt den Einsatz von verschiedenen Katzenfähigkeiten.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }
entries[769] = { ["name"] = "Prankenhieb", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt 3 in der Nähe befindliche Feinde und verursacht 36 Punkt(e) Schaden." }
entries[770] = { ["name"] = "Feenfeuer", ["text"] = "55 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 175. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[772] = { ["name"] = "Verwunden", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Verteidigungshaltung\nVerwundet das Ziel, lässt es 9 Sek. lang bluten und fügt damit 15 Punkt(e) Schaden zu." }
entries[774] = { ["name"] = "Verjüngung", ["text"] = "25 Mana 40 Meter Reichweite\nSofort\nHeilt beim Ziel 12 Sek. lang 32 Punkt(e) Schaden." }
entries[775] = { ["name"] = "Baumgestalt", ["text"] = "20% von Grundmana\nSofort 5 min Abklingzeit\nVerwandelt den Druiden in eine Baumgestalt. Alle negativen körperlichen Effekte werden aufgehoben, der Zaubernde ist für 8 Sek. gegen körperlichen Schaden immun, kann aber nicht angreifen, sich bewegen oder Zaubersprüche wirken. Beschützt den Zaubernden auch vor Verwandlungseffekten.\n\nDer Akt der Gestaltwandlung befreit den Zaubernden von Wurzel-, Schlingen- und Eiskälteeffekten." }
entries[776] = { ["name"] = "Magie aufheben", ["text"] = "24 Mana 30 Meter Reichweite\nSofort 1 sek. Abklingzeit\nHebt die gesamte gegen ein befreundetes Ziel gewirkte Magie auf und verhindert 5 Sek. lang, dass Magie auf das Ziel angewendet werden kann." }
entries[778] = { ["name"] = "Feenfeuer", ["text"] = "75 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 285. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
