entries[781] = { ["name"] = "Rückzug", ["text"] = "50 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVersucht, sich vom Ziel zurückzuziehen und verringert dadurch die Bedrohung. Charakter verlässt Kampfmodus." }
entries[782] = { ["name"] = "Dornen", ["text"] = "60 Mana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 6 Punkt(e) Naturschaden zufügen. Hält 10 Min. lang an." }
