entries[1120] = { ["name"] = "Seelendieb", ["text"] = "55 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 Sek. lang 55 Punkt(e) Schattenschaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Seelensplitter werden für andere Zauber benötigt." }
entries[1121] = { ["name"] = "Umschlingen" }
entries[1122] = { ["name"] = "Inferno", ["text"] = "100% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 1 Stunde Abklingzeit\nReagenzien:\nHöllenstein\nBeschwört einen Meteor aus dem Wirbelnden Nether, der 200 Punkt(e) Feuerschaden verursacht und alle feindlichen Ziele in dem Gebiet 2 Sek. lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 5 Min. lang unter dem Befehl des Zaubernden steht. Sobald die Kontrolle verloren ist, muss die Höllenbestie unterworfen werden, um sie unter Kontrolle zu halten. Kann nur draußen verwendet werden." }
entries[1123] = { ["name"] = "Ritual der Verdammnis", ["text"] = "Wirken in 3 sek.\nLehrt das Ritual der Verdammnis." }
entries[1124] = { ["name"] = "Höllenfeuer II", ["text"] = "27 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nÜberzieht alle Feinde in einem Umkreis von 10 Metern mit 80 bis 91 Punkt(en) Flammenschaden." }
