entries[1129] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. 1392 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1130] = { ["name"] = "Mal des Jägers", ["text"] = "15 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 20. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[1131] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. 2148 Punkt(e) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
