entries[1490] = { ["name"] = "Fluch der Elemente", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel und verringert 5 Min. lang seinen Feuer- und Frostwiderstand um 45. Erhöht außerdem den erlittenen Feuer- und Frostschaden um 6%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1494] = { ["name"] = "Wildtiere aufspüren", ["text"] = "Sofort\nZeigt den Aufenthaltsort aller in der Nähe befindlichen Wildtiere auf der Minikarte an. Es kann immer nur jeweils eine Art des Fährtenlesens benutzt werden." }
entries[1495] = { ["name"] = "Mungobiss", ["text"] = "30 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nEin Gegenangriff auf den Feind fügt ihm 25 Punkt(e) Schaden zu. Kann nur eingesetzt werden, nachdem Ihr ausgewichen seid." }
entries[1499] = { ["name"] = "Eiskältefalle", ["text"] = "50 Mana\nSofort 15 sek. Abklingzeit\nEine Eiskältefalle platzieren, die den ersten sich nähernden Feind einfriert und 10 Sek. lang jegliche Aktion des Feindes verhindert. Jeglicher erlittener Schaden wird das Eis wieder brechen. Die Falle bleibt 1 Min. lang bestehen. Fallen können nur außerhalb von Kampfaktivitäten platziert werden. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[1510] = { ["name"] = "Salve", ["text"] = "350 Mana 8 - 35 Meter Reichweite\nKanalisiert (Wirken in 6 sek.) 1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert kontinuierlich eine Salve Munition auf das Zielgebiet und verursacht 6 Sek. lang pro Sekunde 50 Punkt(e) Arkanschaden bei feindlichen Zielen im Umkreis von 8 Metern." }
entries[1513] = { ["name"] = "Wildtier ängstigen", ["text"] = "35 Mana 10 Meter Reichweite\nWirken in 1.5 sek. 30 sek. Abklingzeit\nJagt einem Wildtier Angst ein, woraufhin es bis zu 10 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
entries[1515] = { ["name"] = "Wildtier zähmen", ["text"] = "60% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 20 sek.)\nBeginnt mit dem Zähmen eines Wildtiers, damit es Euer Gefährte wird. Eure Rüstung ist um 100% verringert, während Ihr Euch 20 Sek. lang auf das Zähmen des Wildtiers fokussiert. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt der Vorgang der Zähmung fehl. Nachdem das Wildtier gezähmt ist, wird es sehr unzufrieden und nicht loyal sein. Füttert das Tier sofort, um es zufrieden zu stellen." }
entries[1516] = { ["name"] = "Schnellschuss", ["text"] = "5 - 30 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert Eure Waffe sofort ab und verursacht so 5 Punkt(e) zusätzlichen Schaden." }
entries[1528] = { ["name"] = "Meister befreien", ["text"] = "5 Meter Reichweite\nSofort\nBefreit Euren Meister von allen Fesseln." }
entries[1535] = { ["name"] = "Totem der Feuernova", ["text"] = "95 Mana\nSofort 15 sek. Abklingzeit\nTools: Feuertotem\nBeschwört ein Totem der Feuernova mit 5 Punkt(en) Gesundheit, das 5 Sek. lang anhält. Wenn es nicht innerhalb von 4 Sek. zerstört wird, fügt das Totem Feinden in einem Umkreis von 10 Metern 53 bis 62 Punkt(e) Feuerschaden zu." }
